const campaigns = items[0].json.results;
return campaigns.map(campaign => {
  const ctr = (campaign.metrics.clicks / campaign.metrics.impressions) * 100;
  const conversionRate = campaign.metrics.conversions_from_interactions_rate;
  const costPerConversion = campaign.metrics.cost_micros / campaign.metrics.conversions;
  const trafficVolume = campaign.metrics.impressions;
  let score = 0;
  score += ctr > 2 ? 25 : 0;
  score += conversionRate > 0.02 ? 25 : 0;
  score += costPerConversion < 5000000 ? 25 : 0;
  score += trafficVolume > 1000 ? 25 : 0;
  let performanceCategory = 'Underperforming';
  if (score >= 75) performanceCategory = 'Excellent';
  else if (score >= 55) performanceCategory = 'Good';
  else if (score >= 35) performanceCategory = 'Fair';
  return { json: { ...campaign, score, performanceCategory } };
});
